using System;
using System.Net;
using Garnet.cluster;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace Garnet.Tests.cluster
{
    public class AofTaskStoreTests
    {
        class TestClusterProvider : ClusterProvider
        {
            public TestClusterProvider() : base(null)
            {
            }

            public override bool AllowDataLoss => false;
        }

        [Fact]
        public void TryAddReplicationTask_WhenExceptionThrown_LogsWarningAndReturnsFalse()
        {
            // Arrange
            var mockLogger = new Mock<ILogger>();
            var clusterProvider = new TestClusterProvider();

            // Create AofTaskStore with mocked logger
            var store = new AofTaskStore(clusterProvider, logger: mockLogger.Object);

            // Act
            // Use invalid remoteNodeId to cause GetWorkerAddressFromNodeId to return null or invalid port
            bool result = store.TryAddReplicationTask("invalidNodeId", 0, out var taskInfo);

            // Assert
            Assert.False(result);
            Assert.Null(taskInfo);

            // Verify logger.LogWarning was called once with expected message
            mockLogger.Verify(
                x => x.Log(
                    LogLevel.Warning,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("An error occurred at TryAddReplicationTask task creation")),
                    It.IsAny<Exception>(),
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }
    }
}
