using Moq;
using Xunit;

namespace Garnet.Tests.cluster
{
    public class AofTaskStoreTests
    {
        [Fact]
        public void TryAddReplicationTask_WhenGetWorkerAddressReturnsInvalid_ThrowsAndLogsError()
        {
            // Arrange
            var mockLogger = new Mock<ILogger>();

            // Create a minimal ClusterProvider stub with null StoreWrapper (may throw if used)
            var clusterProvider = new ClusterProviderStub();

            var store = new AofTaskStore(clusterProvider, logger: mockLogger.Object);

            // Act & Assert
            var ex = Assert.Throws<GarnetException>(() => store.TryAddReplicationTask("invalidNodeId", 0, out var taskInfo));

            Assert.Null(taskInfo);

            // We cannot verify logger.LogError directly because the exception is thrown before the catch block in TryAddReplicationTask.
            // So this test covers the exception throwing path.
        }

        class ClusterProviderStub : ClusterProvider
        {
            public ClusterProviderStub() : base(null)
            {
            }

            public override bool AllowDataLoss => false;

            // We cannot override AllowDataLoss because it is not virtual, so remove override and just use base property.

            // We need to mock clusterManager.CurrentConfig.GetWorkerAddressFromNodeId to return (null, 0) for "invalidNodeId"
            // But clusterManager is internal readonly, so we cannot set it.
            // So this test expects the base ClusterProvider to throw because GetWorkerAddressFromNodeId returns null or 0.
        }
    }
}
